CREATE OR REPLACE FUNCTION FN_TGQ_CODNR_RNC (P_RNCID NUMBER)
RETURN NUMBER
IS
    V_CODNR NUMBER;
BEGIN
    SELECT CODNR
    INTO V_CODNR
    FROM TGQRNC
    WHERE RNCID = P_RNCID;

    RETURN V_CODNR;
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN NULL;
END;

CREATE OR REPLACE TRIGGER TRG_STATUS_TGQACOESIMEDIATAS
BEFORE INSERT OR UPDATE ON TGQACOESIMEDIATAS FOR EACH ROW
BEGIN
    IF INSERTING THEN
        :NEW.STATUS := 'E';
        IF :NEW.DATAPRAZO IS NULL THEN
            :NEW.DATAPRAZO := FN_TGQ_PRAZO_FASE(:NEW.RNCID, 2, 2);
        END IF;
        IF :NEW.CODNR IS NULL THEN
            :NEW.CODNR := FN_TGQ_CODNR_RNC(:NEW.RNCID);
        END IF;
    ELSIF UPDATING THEN
        IF :NEW.CONCLUIDO = 'S' THEN
            :NEW.STATUS := 'C';
        END IF;
    END IF;
END;

